      "Désaccord très fort : Les Écologistes s’oppose très clairement à une baisse des prélèvements sur le travail et le capital accompagnée d’économies sur certaines dépenses publiques et défend une orientation inverse sur l’essentiel de l’arbitrage ; -3 correspond donc à un rejet presque complet de l’affirmation.",
