      "Désaccord net : Les Écologistes est clairement opposé à la concurrence comme outil prioritaire pour améliorer prix, qualité et innovation plutôt qu’un encadrement réglementaire détaillé. Le désaccord est net, mais tous les termes ou toutes les conséquences de la question ne sont pas nécessairement rejetés explicitement, d’où -2.",
      "Désaccord net : Les Écologistes est clairement opposé à une réduction de certaines dépenses ou politiques sociales afin de rétablir les comptes publics. Le désaccord est net, mais tous les termes ou toutes les conséquences de la question ne sont pas nécessairement rejetés explicitement, d’où -2.",
