      "Désaccord net : Les Écologistes est clairement opposé à l’attribution d’un poids politique supérieur aux citoyens démontrant davantage de connaissances institutionnelles ou économiques. Le désaccord est net, mais tous les termes ou toutes les conséquences de la question ne sont pas nécessairement rejetés explicitement, d’où -2.",
